    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the length of the time range
    long duration = end - start;

    // If the duration is less than or equal to the fetch data duration,
    // we can return a single time range with the entire duration
    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, duration));
        return timeRanges;
