 * Create a string supplier which returns unique strings. The returns strings are simply integers starting from start.
 * @param start where to start the sequence
 * @return a string supplier
 */
public static Supplier<String> createStringSupplier(int start) {
    // Define a set to keep track of used integers
    Set<Integer> usedIntegers = new HashSet<>();

    // Define a function that generates a unique integer
    Function<Integer, Integer> generateUniqueInteger = new Function<Integer, Integer>() {
        @Override
        public Integer apply(Integer integer) {
            // If the integer is already used, increment it by 1
            if (usedIntegers.contains(integer)) {
                return integer + 1;
            }

            // If the integer is not used, mark it as used and return it
            usedIntegers.add(integer);
            return integer;
        }
    };

    // Define a function that converts an integer to a string
    Function<Integer, String> convertIntegerToString = new Function<Integer, String>() {
        @Override
        public String apply(Integer integer) {
            return String.valueOf(integer);
        }
    };

    // Return a string supplier that first generates a unique integer using the generateUniqueInteger function,
    // and then converts the integer to a string using the convertIntegerToString function
    return () -> convertIntegerToString.apply(generateUniqueInteger.apply(start));
}

