/**
 * Computes floor($\log_2 (n)$) $+ 1$
 */
private int computeBinaryLog(int n) {
    // Check if n is a power of 2
    if (n == 1) {
        return 0;
    }

    // Compute floor($\log_2 (n)$)
    int log = 0;
    while (n > 1) {
        n = n / 2;
        log++;
    }

    // Add 1 to get the ceiling
    return log + 1;
}

