void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if there are any vertices in the bucket with the minimum label
    if (bucketsByLabel.get(minLabel).isEmpty()) {
        return;
    }

    // Move all vertices from the bucket with the minimum label to the bucket with label 0
    bucketsByLabel.get(minLabel).forEach(vertex -> {
        bucketsByLabel.get(0).add(vertex);
        labels.set(vertex, 0);
    });

    // Clear the bucket with the minimum label
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update the labeling
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            labels.set(i, 0);
        }
    }
}

package utils;

import java.util.Collections;
import java.util.List;
import java.util.Set;

public class BucketsUtil {

  public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) throws IllegalArgumentException {
    if (bucketsByLabel == null || labels == null) {
      throw new IllegalArgumentException("bucketsByLabel and labels cannot be null");
    }
    if (minLabel < 0) {
      throw new IllegalArgumentException("minLabel must be a non-negative value");
    }
    if (bucketsByLabel.size() < minLabel + 1) {
      throw new IllegalArgumentException("bucketsByLabel does not contain enough buckets");
    }
    for (int i = minLabel; i < bucketsByLabel.size(); i++) {
      if (!bucketsByLabel.get(i).isEmpty()) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        bucket.stream().forEach((vertex) -> {
          labels.set(vertex, 0);
        });
        bucketsByLabel.get(i).clear();
      }
    }
